.receipt-ledger-primary{margin-top:12px}
.receipt-advanced{
  margin-top:12px;
  border:1px solid var(--hair);
  border-radius:12px;
  overflow:hidden;
}
.receipt-advanced summary{
  display:flex;
  justify-content:space-between;
  gap:12px;
  padding:12px;
  cursor:pointer;
  list-style:none;
  font-size:.7rem;
  font-weight:800;
}
.receipt-advanced summary::-webkit-details-marker{display:none}
.receipt-advanced summary span{
  color:var(--soft);
  font:700 .58rem var(--font-mono);
}
.receipt-advanced[open] summary{border-bottom:1px solid var(--hair)}
.receipt-advanced .receipt-ledger,
.receipt-advanced .receipt-detail-grid{margin:0;padding:10px}
.receipt-verification{margin-top:12px}

@media(max-width:1180px){
  .hero-workflow-step{min-height:100px}
  .forensic-finding-row{grid-template-columns:minmax(150px,.8fr) minmax(140px,1fr) auto}
  .protected-table-head,.protected-table-row{grid-template-columns:78px minmax(100px,1fr) minmax(100px,1fr) 98px}
}

@media(max-width:820px){
  .hero-workflow{grid-template-columns:1fr 1fr;max-width:none}
  .forensic-finding-row{grid-template-columns:1fr auto}
  .finding-description{grid-column:1/-1}
  .semantic-diff-head{align-items:flex-start;flex-direction:column}
  .diff-tabs{width:100%;overflow-x:auto}
  .diff-tabs button{flex:1;white-space:nowrap}
  .editor-readiness{grid-template-columns:1fr 1fr}
  .protected-table-head{display:none}
  .protected-table-row{
    grid-template-columns:1fr 1fr;
    gap:7px 12px;
  }
  .protected-table-row>span:nth-child(3),
  .protected-table-row>span:nth-child(4){grid-column:auto}
  .protected-table-row>span:nth-child(2)::before,
  .protected-table-row>span:nth-child(3)::before{
    display:block;
    margin-bottom:3px;
    color:var(--soft);
    font:700 .52rem var(--font-mono);
    text-transform:uppercase;
  }
  .protected-table-row>span:nth-child(2)::before{content:"source"}
  .protected-table-row>span:nth-child(3)::before{content:"output"}
}

@media(max-width:680px){
  .hero-workflow{grid-template-columns:1fr}
  .hero-workflow-step{
    min-height:0;
    grid-template-columns:auto minmax(0,1fr);
  }
  .hero-workflow-arrow{display:none}
  .hero-badges{display:none}
  .terminal-card{margin-top:18px}
  .receipt-mini-timeline{overflow:hidden}
  .result-summary-card>div{display:block}
  .result-summary-card strong{display:block;margin-top:4px;text-align:left}
  .evidence-card-grid{grid-template-columns:1fr}
  .evidence-card-grid>div{min-height:0}
  .forensic-preview-head{align-items:flex-start}
  .source-snippet{font-size:.68rem;line-height:1.7;padding:12px}
  .forensic-finding-row{
    grid-template-columns:minmax(0,1fr) auto;
    padding:11px;
  }
  .finding-description{font-size:.66rem}
  .semantic-summary-strip,
  .protected-facts-summary{grid-template-columns:1fr 1fr}
  .semantic-summary-strip span:last-child,
  .protected-facts-summary span:last-child{grid-column:1/-1}
  .editor-readiness{grid-template-columns:1fr 1fr}
  .primary-actions{
    bottom:max(10px,env(safe-area-inset-bottom));
  }
  .primary-actions .primary,
  .primary-actions .secondary{flex:1 1 180px}
  .receipt-overlay{
    align-items:flex-end!important;
    padding:0!important;
  }
  .receipt-drawer{
    position:fixed!important;
    inset:4vh 0 0 0!important;
    width:100%!important;
    max-width:none!important;
    max-height:96vh!important;
    height:96vh!important;
    border-radius:24px 24px 0 0!important;
    overflow-y:auto!important;
    padding:max(14px,env(safe-area-inset-top)) 16px max(18px,env(safe-area-inset-bottom))!important;
  }
  .receipt-drawer-grabber{
    display:block;
    width:42px;
    height:4px;
    margin:0 auto 12px;
    border-radius:999px;
    background:var(--hair);
  }
  .receipt-glance-grid{grid-template-columns:repeat(2,minmax(0,1fr))}
  .receipt-actions{
    position:sticky;
    bottom:0;
    z-index:2;
    margin-inline:-4px;
    padding:10px 4px max(4px,env(safe-area-inset-bottom));
    background:linear-gradient(to top,var(--canvas) 72%,rgba(245,243,238,0));
  }
  .receipt-actions .primary{flex:1}
  .receipt-ledger dd.mono-label,
  .hash-display code{font-size:.64rem;overflow-wrap:anywhere}
  .metadata-transition{flex-wrap:wrap}
  .metadata-transition span{width:100%;margin:0}
}

@media(max-width:430px){
  .hero-workflow-step small{font-size:.64rem}
  .semantic-summary-strip,
  .protected-facts-summary{grid-template-columns:1fr}
  .semantic-summary-strip span:last-child,
  .protected-facts-summary span:last-child{grid-column:auto}
  .protected-table-row{grid-template-columns:1fr}
  .protected-table-row>span{grid-column:auto!important}
  .forensic-finding-row{grid-template-columns:1fr}
  .forensic-finding-row .finding-state{justify-self:start}
  .receipt-glance-grid{grid-template-columns:1fr 1fr}
  .receipt-status-row{align-items:flex-start}
}

@media(max-width:375px){
  .editor-readiness{grid-template-columns:1fr}
  .diff-tabs button{padding-inline:7px;font-size:.58rem}
  .receipt-drawer{padding-inline:13px!important}
}

@media(prefers-reduced-motion:reduce){
  .operation-status.working>span{animation:none}
  .forensic-finding-row,
  .signal-map.interactive .signal-track button{transition:none}
  .signal-map.interactive .signal-track button.selected{box-shadow:0 0 0 2px rgba(46,125,134,.18)}
}

