function messageFrom(payload: unknown, fallback: string) {
  if (payload && typeof payload === "object") {
    const error = (payload as { error?: unknown }).error;
    if (typeof error === "string") return error;
    if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
      return (error as { message: string }).message;
    }
  }
  return fallback;
}
function sleep(ms: number) { return new Promise(resolve => setTimeout(resolve, ms)); }

export function AccountBar() {
  const supabase = useMemo(() => { try { return createClient(); } catch { return null; } }, []);
  const [identity, setIdentity] = useState<IdentityState | null>(null);
  const [balance, setBalance] = useState<BalanceState | null>(null);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [challengeToken, setChallengeToken] = useState<string | null>(null);
  const [challengeReset, setChallengeReset] = useState(0);
  const onChallenge = useCallback((token: string | null) => setChallengeToken(token), []);

  const refreshIdentity = useCallback(async () => {
    if (!supabase) return false;
    const { data, error } = await supabase.auth.getUser();
    if (error || !data.user) { setIdentity(null); setBalance(null); return false; }
    setIdentity({ userId: data.user.id, isAnonymous: Boolean(data.user.is_anonymous) });
    const response = await fetch("/api/billing/balance", { cache: "no-store" });
    if (response.status === 401) { setIdentity(null); setBalance(null); return false; }
    if (response.ok) {
      const payload = await response.json();
      setBalance(payload.balance);
      return true;
    }
    return false;
  }, [supabase]);

  useEffect(() => {
    let cancelled = false;
    const refresh = () => { void refreshIdentity().catch(() => { if (!cancelled) setMessage("Account status could not be refreshed."); }); };
    const initialRefresh = window.setTimeout(refresh, 0);
    const changed = () => { if (!cancelled) refresh(); };
    window.addEventListener("provenance:account-changed", changed);
    return () => { cancelled = true; window.clearTimeout(initialRefresh); window.removeEventListener("provenance:account-changed", changed); };
  }, [refreshIdentity]);

  useEffect(() => {
    const url = new URL(window.location.href);
    const purchaseParam = url.searchParams.get("purchase");
    if (url.searchParams.get("checkout") !== "success" || !purchaseParam) return;
    const purchaseId: string = purchaseParam;
    let cancelled = false;
    async function reconcile() {
      setMessage("Payment received. Reconciling credits…");
      for (let attempt = 0; attempt < 12 && !cancelled; attempt += 1) {
        const response = await fetch("/api/account/history", { cache: "no-store" });
        if (response.ok) {
          const payload = await response.json();
          const purchases = Array.isArray(payload?.history?.purchases) ? payload.history.purchases : [];
          const match = purchases.find((item: unknown) => item && typeof item === "object" && (item as { id?: unknown }).id === purchaseId) as { status?: string; refund?: unknown } | undefined;
          if (match?.status === "completed" || match?.refund) {
            await refreshIdentity();
            const refunded = Boolean(match.refund);
            setMessage(refunded ? "Payment was refunded during reconciliation." : "Payment confirmed. Credits are available.");
            emitReceipt({
              id: purchaseId,
              title: refunded ? "Payment refund reconciliation" : "Credit purchase reconciliation",
              operation: refunded ? "payment.refund" : "payment.complete",
              status: refunded ? "refunded" : "validated",
              verification: refunded
                ? "Stripe and authoritative account history agree that this purchase was refunded."
                : "Stripe Checkout and authoritative account history agree that this purchase completed.",
              details: [{ label: "Purchase", value: purchaseId }, { label: "State", value: refunded ? "refunded" : "completed" }],
            });
            url.searchParams.delete("checkout");
            url.searchParams.delete("purchase");
            window.history.replaceState({}, "", `${url.pathname}${url.search}${url.hash}`);
            return;
          }
        }
        await sleep(500);
      }
      if (!cancelled) setMessage("Payment was received, but credit reconciliation is still pending. Your payment will not be credited twice; refresh shortly.");
    }
    void reconcile();
    return () => { cancelled = true; };
  }, [refreshIdentity]);

  function resetChallenge() { setChallengeToken(null); setChallengeReset(value => value + 1); }
  async function startGuest() {
    if (!challengeToken) return;
    setBusy(true); setMessage(null);
    try {
      const response = await fetch("/api/auth/anonymous", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ challengeToken, forClean: false }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(messageFrom(payload, "Could not start a guest session."));
      setIdentity({ userId: payload.userId, isAnonymous: payload.isAnonymous !== false });
      setBalance(payload.balance);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Could not start a guest session."); }
    finally { setBusy(false); resetChallenge(); }
  }
  async function google() {
    if (!supabase) return;
    setBusy(true); setMessage(null);
    const redirectTo = `${window.location.origin}/auth/callback?next=/&promo=${identity?.isAnonymous ? "1" : "0"}`;
    const result = identity?.isAnonymous
      ? await supabase.auth.linkIdentity({ provider: "google", options: { redirectTo } })
      : await supabase.auth.signInWithOAuth({ provider: "google", options: { redirectTo } });
    if (result.error) { setMessage("Google sign-in could not be started."); setBusy(false); }
  }
  async function signOut() {
    setBusy(true);
    await fetch("/api/auth/signout", { method: "POST" });
    setIdentity(null); setBalance(null); setBusy(false);
  }
  async function buy(packId: CreditPackId) {
    if (!challengeToken) return;
    setBusy(true); setMessage(null);
    try {
      const response = await fetch("/api/billing/checkout", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ packId, challengeToken }) });
      const payload = await response.json();
      if (!response.ok) throw new Error(messageFrom(payload, "Checkout is not available."));
      window.location.assign(payload.url);
    } catch (error) { setMessage(error instanceof Error ? error.message : "Checkout is not available."); setBusy(false); resetChallenge(); }
  }

  return <section className={styles.bar} aria-label="Account and credits">
    <div className={styles.identity}><p className={styles.eyebrow}>Usage & account</p><strong>{identity ? (identity.isAnonymous ? "Guest session" : "Signed-in account") : "No account yet"}</strong><span className={styles.subtext}>{balance ? `${balance.available} available · ${balance.held} processing · ${balance.settled} settled` : "Inspection is free. An account is needed only when you run a paid action."}</span></div>
    {balance && <div className={styles.metrics} aria-label="Credit balance"><div><span>Available</span><strong>{balance.available}</strong></div><div><span>Held</span><strong>{balance.held}</strong></div><div><span>Settled</span><strong>{balance.settled}</strong></div></div>}
    <div className={styles.actions}>
      {!identity && <button disabled={busy || !supabase || !challengeToken} onClick={startGuest}>Start guest now</button>}
      {(!identity || identity.isAnonymous) && <button disabled={busy || !supabase} onClick={google}>{identity ? "Upgrade with Google (+3 once)" : "Sign in with Google"}</button>}
      {identity && Object.values(CREDIT_PACKS).map(pack => <button className={styles.pack} disabled={busy || !challengeToken} key={pack.id} onClick={() => buy(pack.id)}>+{pack.credits} · ${pack.priceUsd.toFixed(2)}</button>)}
      {identity && <button className={styles.secondary} disabled={busy} onClick={signOut}>Sign out</button>}
    </div>
    <TurnstileWidget action="account" onToken={onChallenge} resetKey={challengeReset} />
    <div className={styles.commitment}><span className="status-dot"/>Usage is committed only after verified successful work.</div>
    {message && <p className={styles.message} role="status">{message}</p>}
  </section>;
}

