  if(active==="subscriptions")return <><AdminHeading title="Subscriptions" copy="Monthly credits are granted only from idempotent paid invoices. Existing pay-as-you-go packs remain separate but share FIFO credit lots."/><div className="admin-kpis"><Metric label="Active / trialing" value={data.activeSubscriptions}/><Metric label="Past due / unpaid" value={data.pastDueSubscriptions}/><Metric label="TEST MRR" value={money(data.testMrrCents)}/><Metric label="TEST ARR projection" value={money(data.testMrrCents*12)}/></div><div className="admin-table-card"><h2>{data.activeSubscriptions?"Subscription portfolio active":"No subscription activity yet"}</h2><p>{data.activeSubscriptions?"Current TEST MRR is derived from authoritative active/trialing subscription plan records. Invoice-paid grants remain idempotent by Stripe invoice ID.":"Subscription tracking is ready for the first Stripe TEST subscription. Billing Portal remains server-authoritative for cancellation."}</p></div></>;
  if(active==="finops")return <><AdminHeading title="FinOps" copy="Actual, estimated, manual, and confirmed-zero cost sources remain visibly distinct. No estimate is represented as an invoice."/><div className="admin-kpis"><Metric label="Current window cost" value={microsMoney(data.costMicros)}/><Metric label="TEST net revenue" value={money(netRevenue)}/><Metric label="Contribution margin" value={contributionMargin}/><Metric label="Cost / successful job" value={data.successfulJobs?microsMoney(Math.round(data.costMicros/data.successfulJobs)):"—"}/><Metric label="Providers with cost evidence" value={data.costByProvider.length}/></div><Chart title="Cost per day" values={day.map((row)=>row.costMicros)}/><div className="admin-table-card"><h2>Provider cost evidence</h2>{data.costByProvider.length?<ul>{data.costByProvider.map((cost)=><li key={cost.provider}><strong>{cost.provider}</strong><span>{microsMoney(cost.amountMicros)} · {cost.source}</span></li>)}</ul>:<p>No provider cost events yet. The console reports the absence explicitly rather than inventing cost coverage.</p>}</div></>;
  if(active==="operations")return <><AdminHeading title="Operations" copy="Health evidence and reconciliation status are server-side only. Secrets are never rendered."/><div className="admin-kpis"><Metric label="Database schema" value={data.schemaVersion}/><Metric label="Stripe mode" value="TEST"/><Metric label="Metrics generated" value={new Date(data.generatedAt).toLocaleString("en-US",{timeZone:"UTC"})+" UTC"}/></div><div className="admin-table-card"><h2>Runtime certification</h2><p>Deployment SHA and complete dependency readiness are authoritative at <code>/api/health</code> and <code>/api/readiness</code>. Scheduled reconciliation and daily rollups use server-only credentials.</p></div></>;
  if(active==="audit")return <><AdminHeading title="Audit" copy="Admin mutations record actor, request ID, result, object identifier, and safe metadata—never customer content or credentials."/><div className="admin-table-card"><h2>Privacy-safe audit log</h2><p>The database denies browser access to private audit tables, and the schema contains no raw content fields.</p></div></>;
  if(active==="system")return <><AdminHeading title="System" copy="Configuration values and secrets stay server-side. Runtime readiness is exposed only as safe configured/missing status."/><div className="admin-kpis"><Metric label="Schema version" value={data.schemaVersion}/><Metric label="Stripe mode" value="TEST"/><Metric label="Admin authorization" value="Server-side"/><Metric label="Automatic Git deploys" value="Disabled"/></div><div className="admin-table-card"><h2>Release evidence</h2><p>Use <code>/api/health</code> for the exact deployed SHA and <code>/api/readiness</code> for database and configuration readiness. The release workflow refuses deployment when Production preflight fails.</p></div></>;
  return <><AdminHeading title="Overview" copy="A ten-second operational readout. All metrics are server-derived and intentionally safe for a privacy-first product."/><div className="admin-kpis"><Metric label="Registered users" value={data.registeredUsers}/><Metric label="New users 7D" value={data.newUsers7d}/><Metric label="DAU / WAU / MAU" value={`${data.dau} / ${data.wau} / ${data.mau}`}/><Metric label="Jobs today" value={data.jobsToday}/><Metric label="Success rate" value={successRate}/><Metric label="Credits outstanding" value={data.creditsOutstanding}/><Metric label="TEST gross revenue" value={money(data.testGrossRevenueCents)}/><Metric label="TEST net revenue" value={money(netRevenue)}/><Metric label="TEST MRR" value={money(data.testMrrCents)}/><Metric label="Active subscriptions" value={data.activeSubscriptions}/><Metric label="Current cost" value={microsMoney(data.costMicros)}/><Metric label="Contribution margin" value={contributionMargin}/></div><div className="admin-grid"><Chart title="Daily registrations" values={day.map((row)=>row.registeredUsers)}/><Chart title="Operations per day" values={day.map((row)=>row.jobs)}/></div></>;
}
function AdminHeading({title,copy}:{title:string;copy:string}){return <header className="admin-section-heading"><p className="eyebrow">{title}</p><h1>{title}</h1><p>{copy}</p></header>;}

"use client";

import { useMemo, useState } from "react";
import {
  ARTIFACT_KINDS,
  createArtifactReceipt,
  type ArtifactKind,
  type ArtifactProvenanceReceipt,
  verifyArtifactReceipt,
  type ArtifactVerificationResult,
} from "@/lib/artifacts/provenance";

const SAMPLE = `# Example Agent Skill

Name: research-summarizer
Purpose: Summarize supplied evidence without inventing claims.

Instructions:
- Cite the supplied evidence.
- Preserve uncertainty.
- Do not expose credentials.
`;

function downloadJson(payload: unknown, name: string) {
  const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
  const url = URL.createObjectURL(blob);
  const anchor = document.createElement("a");
  anchor.href = url;
  anchor.download = name;
  anchor.click();
  setTimeout(() => URL.revokeObjectURL(url), 0);
}

export function ArtifactProvenanceWorkbench() {
  const [artifact, setArtifact] = useState(SAMPLE);
  const [kind, setKind] = useState<ArtifactKind>("agent-skill");
  const [name, setName] = useState("research-summarizer");
  const [version, setVersion] = useState("1.0.0");
  const [previousHash, setPreviousHash] = useState("");
  const [receipt, setReceipt] = useState<ArtifactProvenanceReceipt | null>(null);
  const [receiptJson, setReceiptJson] = useState("");
  const [verification, setVerification] = useState<ArtifactVerificationResult | null>(null);
  const [error, setError] = useState<string | null>(null);
  const blocked = useMemo(() => receipt?.hygiene.status === "blocked", [receipt]);

  async function generate() {
    setError(null);
    setVerification(null);
    try {
      const next = await createArtifactReceipt(artifact, {
        kind,
        artifactName: name,
        artifactVersion: version,
        previousArtifactHash: previousHash || undefined,
      });
      setReceipt(next);
      setReceiptJson(JSON.stringify(next, null, 2));
    } catch (cause) {
      setError(cause instanceof Error ? cause.message : "Could not create the provenance receipt.");
    }
  }

  async function verify() {
    setError(null);
    try {
      const parsed = JSON.parse(receiptJson) as ArtifactProvenanceReceipt;
      if (parsed.version !== "artifact-provenance-v1" || typeof parsed.receiptHash !== "string") {
        throw new Error("Receipt is not an artifact-provenance-v1 receipt.");
      }
      setVerification(await verifyArtifactReceipt(artifact, parsed));
    } catch (cause) {
      setVerification(null);
      setError(cause instanceof Error ? cause.message : "Could not verify this receipt.");
    }
  }

  return <section className="artifact-provenance-section" aria-label="Artifact provenance workbench">
    <div className="section-heading">
      <div>
        <p className="eyebrow">Artifact provenance</p>
        <h2>Hash the artifact. Verify the receipt.</h2>
        <p>Create local SHA-256 identity and self-hashed receipts for prompts, agent skills, configuration, JSON artifacts, and other AI assets. Optional previous hashes form an explicit version chain.</p>
      </div>
      <span className="pill local-pill">Local · no account</span>
    </div>

    <div className="artifact-grid">
      <div className="panel">
        <div className="panel-heading"><div><p className="eyebrow">Artifact</p><h2>Canonical identity</h2></div><span className="pill">SHA-256</span></div>
        <div className="artifact-controls">
          <label>Artifact kind
            <select value={kind} onChange={(event) => { setKind(event.target.value as ArtifactKind); setReceipt(null); }}>
              {ARTIFACT_KINDS.map((item) => <option value={item} key={item}>{item}</option>)}
            </select>
          </label>
          <label>Name<input value={name} onChange={(event) => setName(event.target.value)} placeholder="optional" /></label>
          <label>Version<input value={version} onChange={(event) => setVersion(event.target.value)} placeholder="optional" /></label>
        </div>
        <label>Previous artifact SHA-256 (optional chain link)
          <input value={previousHash} onChange={(event) => setPreviousHash(event.target.value)} placeholder="64 hex characters" spellCheck={false} />
        </label>
        <textarea value={artifact} onChange={(event) => { setArtifact(event.target.value); setReceipt(null); setVerification(null); }} spellCheck={false} aria-label="Artifact content" />
        <div className="actions">
          <button className="primary" onClick={() => void generate()} disabled={!artifact}>Generate local receipt</button>
          <button className="ghost" onClick={() => { setArtifact(SAMPLE); setKind("agent-skill"); setReceipt(null); setVerification(null); }}>Try example</button>
        </div>
        <div className="trust-note"><span className="status-dot"/><div><strong>Content stays in this browser.</strong><p>Artifact content is canonicalized and hashed locally. The receipt stores hashes and hygiene results, not a server-side copy of the artifact.</p></div></div>
        {error && <div className="error-card" role="alert">{error}</div>}
      </div>

      <div className="panel">
        <div className="panel-heading"><div><p className="eyebrow">Integrity receipt</p><h2>{receipt ? "Receipt generated" : "Waiting for artifact"}</h2></div>{receipt && <span className={`score ${blocked ? "warn" : "ok"}`}>{receipt.hygiene.status}</span>}</div>
        {!receipt ? <div className="empty-state compact"><div><span className="empty-symbol">#</span><strong>No receipt yet</strong><p>Generate a receipt to see the canonical artifact hash, receipt hash, version-chain link, and deterministic hygiene findings.</p></div></div> : <>
          <div className="artifact-hashes">
            <div><span>Artifact SHA-256</span><code>{receipt.artifactHash}</code></div>
            <div><span>Receipt SHA-256</span><code>{receipt.receiptHash}</code></div>
            <div><span>Canonicalization</span><strong>{receipt.canonicalization}</strong></div>
            <div><span>Previous artifact</span><code>{receipt.previousArtifactHash ?? "none"}</code></div>
          </div>
          <div className="artifact-findings">
            {receipt.hygiene.findings.length === 0 ? <div className="success-card">No deterministic hygiene findings.</div> : receipt.hygiene.findings.map((item) => <div className={`artifact-finding ${item.severity}`} key={item.code}><strong>{item.code}</strong><span>{item.count}</span><p>{item.message}</p></div>)}
          </div>
          <div className="actions">
            <button className="ghost" onClick={() => downloadJson(receipt, `artifact-provenance-${receipt.artifactHash.slice(0, 12)}.json`)}>Export receipt JSON</button>
          </div>
        </>}

        <div className="artifact-verify">
          <p className="eyebrow">Re-verify</p>
          <textarea aria-label="Artifact receipt JSON" value={receiptJson} onChange={(event) => { setReceiptJson(event.target.value); setVerification(null); }} placeholder="Paste an artifact-provenance-v1 receipt…" spellCheck={false} />
          <button className="secondary" onClick={() => void verify()} disabled={!artifact || !receiptJson}>Verify artifact + receipt</button>
          {verification && <div className={`verification-box ${verification.artifactMatches && verification.receiptIntegrity && verification.chainLinkWellFormed ? "" : "verification-failed"}`}>
            <strong>{verification.artifactMatches && verification.receiptIntegrity && verification.chainLinkWellFormed ? "Integrity verified" : "Verification failed"}</strong>
            <div className="verification-stats">
              <span>artifact {verification.artifactMatches ? "match" : "mismatch"}</span>
              <span>receipt {verification.receiptIntegrity ? "intact" : "modified"}</span>
              <span>chain {verification.chainLinkWellFormed ? "well formed" : "invalid"}</span>
            </div>
          </div>}
        </div>
      </div>
    </div>
  </section>;
}

"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { createClient } from "@/lib/supabase/client";

function callbackUrl(origin: string, next: string, promo: boolean) {
  const url = new URL("/auth/callback", origin);
  url.searchParams.set("next", next);
  url.searchParams.set("promo", promo ? "1" : "0");
  return url.toString();
}

export function AuthForm() {
  const router = useRouter();
  const supabase = useMemo(() => { try { return createClient(); } catch { return null; } }, []);
  const [mode, setMode] = useState<"signin" | "signup">("signup");
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [anonymous, setAnonymous] = useState(false);
  const [identityChecked, setIdentityChecked] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    async function inspectIdentity() {
      if (!supabase) { if (!cancelled) setIdentityChecked(true); return; }
      const { data } = await supabase.auth.getUser();
      if (!cancelled) {
        setAnonymous(Boolean(data.user?.is_anonymous));
        setIdentityChecked(true);
      }
    }
    void inspectIdentity().catch(() => { if (!cancelled) setIdentityChecked(true); });
    return () => { cancelled = true; };
  }, [supabase]);

  async function claimPromo() {
    await fetch("/api/auth/claim-signup-promo", { method: "POST", headers: { "content-type": "application/json" }, body: "{}" });
  }

  async function submit(event: FormEvent) {
    event.preventDefault();
    if (!supabase || !identityChecked) return;
    setBusy(true); setMessage(null);
    try {
      if (mode === "signup" && anonymous) {
        const redirectTo = callbackUrl(window.location.origin, "/auth/update-password?upgrade=1", true);
        const { data, error } = await supabase.auth.updateUser({ email }, { emailRedirectTo: redirectTo });
        if (error) throw error;
        if (data.user && !data.user.is_anonymous) {
          await claimPromo();
          router.push("/auth/update-password?upgrade=1");
          router.refresh();
          return;
        }
        setMessage("Check your email to verify this address. After verification you will choose a password; this keeps the same guest user, credits, and history.");
        return;
      }

      if (mode === "signup") {
        const redirectTo = callbackUrl(window.location.origin, "/account", true);
        const { data, error } = await supabase.auth.signUp({ email, password, options: { emailRedirectTo: redirectTo } });
        if (error) throw error;
        if (data.session) {
          await claimPromo();
          router.push("/account");
          router.refresh();
          return;
        }
        setMessage("Check your email to confirm the account. The one-time signup credit grant is claimed after confirmation.");
        return;
      }

      if (anonymous) {
        setMessage("This browser currently has a guest account with its own credit history. To avoid silently replacing that guest session, convert it with Sign up or Google instead of signing into a different existing account here.");
        return;
      }
      const { error } = await supabase.auth.signInWithPassword({ email, password });
      if (error) throw error;
      router.push("/account");
      router.refresh();
    } catch (cause) {
      setMessage(cause instanceof Error ? cause.message : "Authentication could not be completed.");
    } finally { setBusy(false); }
  }

  async function google() {
    if (!supabase || !identityChecked) return;
    setBusy(true); setMessage(null);
    const redirectTo = callbackUrl(window.location.origin, "/account", mode === "signup" || anonymous);
    const result = anonymous
      ? await supabase.auth.linkIdentity({ provider: "google", options: { redirectTo } })
      : await supabase.auth.signInWithOAuth({ provider: "google", options: { redirectTo } });
    if (result.error) { setMessage("Google sign-in could not be started."); setBusy(false); }
  }

  async function resetPassword() {
    if (!supabase || !email) { setMessage("Enter your email first."); return; }
    if (anonymous) { setMessage("Convert or leave the current guest session before requesting a password reset for another account."); return; }
    setBusy(true); setMessage(null);
    const redirectTo = `${window.location.origin}/auth/update-password`;
    const { error } = await supabase.auth.resetPasswordForEmail(email, { redirectTo });
    setMessage(error ? error.message : "If the address is eligible, a password-reset email has been sent.");
    setBusy(false);
  }

  const anonymousUpgrade = anonymous && mode === "signup";
  return <div className="panel">
    <div className="panel-heading"><div><p className="eyebrow">Account</p><h2>{anonymousUpgrade ? "Keep this guest account" : mode === "signup" ? "Create an account" : "Sign in"}</h2></div><span className="pill">+3 signup credits once</span></div>
    {anonymous && <div className="notice-card">A guest session is active. Converting it preserves the same Supabase user ID so existing guest credits and ledger history stay attached.</div>}
    <div className="actions"><button type="button" className={mode === "signup" ? "primary" : "ghost"} onClick={() => { setMode("signup"); setMessage(null); }}>Sign up</button><button type="button" className={mode === "signin" ? "primary" : "ghost"} onClick={() => { setMode("signin"); setMessage(null); }}>Sign in</button></div>
    <form onSubmit={submit}>
      <label>Email<input type="email" autoComplete="email" required value={email} onChange={event => setEmail(event.target.value)} /></label>
      {!anonymousUpgrade && <label>Password<input type="password" minLength={8} autoComplete={mode === "signup" ? "new-password" : "current-password"} required value={password} onChange={event => setPassword(event.target.value)} /></label>}
      {anonymousUpgrade && <p className="privacy-note">Supabase requires the email identity to be verified before a password can be added to an anonymous user. We will send the verification first, then ask you to choose the password.</p>}
      <div className="actions"><button className="primary" disabled={busy || !supabase || !identityChecked} type="submit">{busy ? "Working…" : anonymousUpgrade ? "Verify email and keep guest history" : mode === "signup" ? "Create account" : "Sign in"}</button><button className="secondary" disabled={busy || !supabase || !identityChecked} type="button" onClick={google}>{anonymous ? "Link Google and keep guest history" : "Continue with Google"}</button>{mode === "signin" && <button className="ghost" disabled={busy} type="button" onClick={resetPassword}>Forgot password</button>}</div>
    </form>
    <p className="privacy-note">Guest upgrades use Supabase identity linking instead of creating a replacement user. Ordinary sign-in never claims the signup promotion.</p>
    {message && <div className="notice-card" role="status">{message}</div>}
  </div>;
}

"use client";

import { FormEvent, useState } from "react";

export function ContactMailto({ supportEmail }: { supportEmail?: string | null }) {
  const [subject, setSubject] = useState("");
  const [message, setMessage] = useState("");
  function submit(event: FormEvent) {
    event.preventDefault();
    if (!supportEmail) return;
    const href = `mailto:${supportEmail}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(message)}`;
    window.location.href = href;
  }
  return <form className="panel contact-form" onSubmit={submit}>
    <div className="panel-heading"><div><p className="eyebrow">Private handoff</p><h2>Open a draft in your email app.</h2></div><span className="pill">mailto only</span></div>
    <label>Subject<input required maxLength={160} value={subject} onChange={event => setSubject(event.target.value)} placeholder="Billing, privacy, account data…" /></label>
    <label>Message<textarea required maxLength={5_000} value={message} onChange={event => setMessage(event.target.value)} placeholder="Write the message that should go into your email client…" /></label>
    <div className="actions"><button className="primary" type="submit" disabled={!supportEmail}>Send message</button></div>
    <div className="trust-note"><span className="status-dot"/><div><strong>No contact POST endpoint.</strong><p>This form does not send or store the message in Provenance Cleaner. It only opens a draft in your email client.{!supportEmail ? " A production support address still needs to be configured." : ""}</p></div></div>
  </form>;
}

"use client";

import { useCallback, useState } from "react";
import { useRouter } from "next/navigation";
import { CREDIT_PACKS, type CreditPackId } from "@/lib/billing/catalog";
import { TurnstileWidget } from "@/components/turnstile-widget";

function messageFrom(payload: unknown, fallback: string) {
  if (payload && typeof payload === "object") {
    const error = (payload as { error?: unknown }).error;
    if (error && typeof error === "object" && typeof (error as { message?: unknown }).message === "string") {
      return (error as { message: string }).message;
    }
    if (typeof error === "string") return error;
  }
  return fallback;
}

export function CreditPackGrid({ compact = false }: { compact?: boolean }) {
  const router = useRouter();
  const [challengeToken, setChallengeToken] = useState<string | null>(null);
  const [resetKey, setResetKey] = useState(0);
  const [busyPack, setBusyPack] = useState<CreditPackId | null>(null);
  const [message, setMessage] = useState<string | null>(null);
  const onToken = useCallback((token: string | null) => setChallengeToken(token), []);

  async function buy(packId: CreditPackId) {
    if (!challengeToken) return;
    setBusyPack(packId);
    setMessage(null);
    try {
      const response = await fetch("/api/billing/checkout", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ packId, challengeToken }),
      });
      const payload = await response.json();
      if (response.status === 401) {
        router.push("/auth");
        return;
      }
      if (!response.ok || typeof payload?.url !== "string") {
        throw new Error(messageFrom(payload, "Checkout is not available."));
      }
      window.location.assign(payload.url);
    } catch (error) {
      setMessage(error instanceof Error ? error.message : "Checkout is not available.");
      setChallengeToken(null);
      setResetKey(value => value + 1);
      setBusyPack(null);
    }
  }

  if (compact) {
    return <div className="account-topup">
      <div className="account-topup-head">
        <div><p className="eyebrow">One-time top up</p><h2>Add processing allowance without a subscription.</h2></div>
        <span className="pill">Stripe TEST</span>
      </div>
      <div className="account-topup-actions">
        {Object.values(CREDIT_PACKS).map(pack => <button
          key={pack.id}
          className="ghost"
          type="button"
          disabled={!challengeToken || busyPack !== null}
          onClick={() => void buy(pack.id)}
        >
          {busyPack === pack.id ? "Opening Stripe…" : `${pack.credits} units · ${pack.priceUsd.toFixed(2)}`}
        </button>)}
      </div>
      <TurnstileWidget action="account" onToken={onToken} resetKey={resetKey} />
      {message && <p className="notice-card" role="status">{message}</p>}
    </div>;
  }

  return <div>
    <div className="credit-pack-grid">
      {Object.values(CREDIT_PACKS).map((pack, index) => <article className={`credit-pack-card ${index === 1 ? "featured" : ""}`} key={pack.id}>
        <span className="mono-label">{index === 1 ? "MOST FLEXIBLE" : "ONE-TIME PACK"}</span>
        <strong>{pack.credits}<small> units</small></strong>
        <h2>{pack.label}</h2>
        <p>{`$${pack.priceUsd.toFixed(2)} · hosted Stripe TEST Checkout · no subscription`}</p>
        <div className="pack-unit">{`$${(pack.priceUsd / pack.credits).toFixed(2)} / unit`}</div>
        <button className={index === 1 ? "secondary" : "primary"} type="button" disabled={!challengeToken || busyPack !== null} onClick={() => void buy(pack.id)}>
          {busyPack === pack.id ? "Opening Stripe…" : `Buy ${pack.label}`}
        </button>
      </article>)}
    </div>
    <TurnstileWidget action="account" onToken={onToken} resetKey={resetKey} />
    {message && <p className="notice-card" role="status">{message}</p>}
  </div>;
}
